## 查询优化技巧

**1. 使用投影**：
```csharp
// 不推荐：加载整个实体
var users = await _context.Users.ToListAsync();

// 推荐：只查询需要的字段
var userDtos = await _context.Users
    .Select(u => new { u.Id, u.Name })
    .ToListAsync();
```

**2. 分页查询**：
```csharp
var pagedUsers = await _context.Users
    .OrderBy(u => u.Id)
    .Skip((page - 1) * pageSize)
    .Take(pageSize)
    .ToListAsync();
```

**3. 使用 Any 而非 Count**：
```csharp
// 不推荐
if (await _context.Users.CountAsync(u => u.IsActive) > 0)

// 推荐
if (await _context.Users.AnyAsync(u => u.IsActive))
```

**4. 编译查询**：
```csharp
private static readonly Func<AppDbContext, int, User> GetUserById =
    EF.CompileQuery((AppDbContext context, int id) =>
        context.Users.FirstOrDefault(u => u.Id == id));

var user = GetUserById(_context, 1);
```

## 批量操作优化

**批量插入**：
```csharp
// 使用 AddRange
await _context.Users.AddRangeAsync(users);
await _context.SaveChangesAsync();

// 使用 EFCore.BulkExtensions（第三方库）
await _context.BulkInsertAsync(users);
```

**批量更新**：
```csharp
// EF Core 7+ ExecuteUpdate
await _context.Users
    .Where(u => u.CreatedAt < DateTime.UtcNow.AddDays(-30))
    .ExecuteUpdateAsync(s => s
        .SetProperty(u => u.IsActive, false));

// 使用第三方库
await _context.BulkUpdateAsync(users);
```

## 读写分离

```csharp
// 配置多个 DbContext
services.AddDbContext<ReadDbContext>(options =>
    options.UseSqlServer(readConnectionString));

services.AddDbContext<WriteDbContext>(options =>
    options.UseSqlServer(writeConnectionString));

// 使用
public class UserService
{
    private readonly ReadDbContext _readContext;
    private readonly WriteDbContext _writeContext;

    public async Task<User> GetUserAsync(int id)
    {
        return await _readContext.Users.FindAsync(id);
    }

    public async Task UpdateUserAsync(User user)
    {
        _writeContext.Users.Update(user);
        await _writeContext.SaveChangesAsync();
    }
}
```

using System;
using System.Collections.Generic;
using System.Diagnostics;
using System.Linq;
using System.Threading.Tasks;
using Microsoft.EntityFrameworkCore;
using Microsoft.Extensions.Logging;

namespace EFCorePerformanceDemo
{
    public class User
    {
        public int Id { get; set; }
        public string Name { get; set; }
        public string Email { get; set; }
        public bool IsActive { get; set; } = true;
        public DateTime CreatedAt { get; set; } = DateTime.UtcNow;
        public ICollection<Order> Orders { get; set; } = new List<Order>();
    }

    public class Order
    {
        public int Id { get; set; }
        public string ProductName { get; set; }
        public decimal Price { get; set; }
        public int Quantity { get; set; }
        public DateTime OrderDate { get; set; } = DateTime.UtcNow;
        public int UserId { get; set; }
        public User User { get; set; }
    }

    public class PerformanceDbContext : DbContext
    {
        public DbSet<User> Users { get; set; }
        public DbSet<Order> Orders { get; set; }

        public PerformanceDbContext(DbContextOptions<PerformanceDbContext> options)
            : base(options) { }

        protected override void OnModelCreating(ModelBuilder modelBuilder)
        {
            modelBuilder.Entity<User>(entity =>
            {
                entity.HasIndex(e => e.Email).IsUnique();
                entity.HasIndex(e => e.IsActive);
                entity.HasIndex(e => e.CreatedAt);
            });

            modelBuilder.Entity<Order>(entity =>
            {
                entity.HasIndex(e => e.UserId);
                entity.HasIndex(e => e.OrderDate);
            });
        }
    }

    // 性能优化示例
    public class OptimizedQueries
    {
        private readonly PerformanceDbContext _context;
        private readonly ILogger<OptimizedQueries> _logger;

        public OptimizedQueries(
            PerformanceDbContext context,
            ILogger<OptimizedQueries> logger)
        {
            _context = context;
            _logger = logger;
        }

        // N+1 问题示例
        public async Task<List<User>> GetUsersWithOrders_NPlus1()
        {
            // 问题代码：产生 N+1 查询
            var users = await _context.Users.ToListAsync();
            foreach (var user in users)
            {
                // 每次循环都会查询一次数据库
                user.Orders = await _context.Orders
                    .Where(o => o.UserId == user.Id)
                    .ToListAsync();
            }
            return users;
        }

        // 解决 N+1：使用 Include
        public async Task<List<User>> GetUsersWithOrders_Include()
        {
            return await _context.Users
                .Include(u => u.Orders)
                .ToListAsync();
        }

        // 解决 N+1：使用投影
        public async Task<List<UserDto>> GetUsersWithOrders_Projection()
        {
            return await _context.Users
                .Select(u => new UserDto
                {
                    Id = u.Id,
                    Name = u.Name,
                    OrderCount = u.Orders.Count,
                    TotalSpent = u.Orders.Sum(o => o.Price * o.Quantity)
                })
                .ToListAsync();
        }

        // AsNoTracking 示例
        public async Task<List<User>> GetActiveUsers_NoTracking()
        {
            return await _context.Users
                .AsNoTracking()
                .Where(u => u.IsActive)
                .ToListAsync();
        }

        // 分页查询
        public async Task<List<User>> GetUsersPaged(int page, int pageSize)
        {
            return await _context.Users
                .AsNoTracking()
                .OrderBy(u => u.Id)
                .Skip((page - 1) * pageSize)
                .Take(pageSize)
                .ToListAsync();
        }

        // 编译查询
        private static readonly Func<PerformanceDbContext, int, User> GetUserById =
            EF.CompileQuery((PerformanceDbContext context, int id) =>
                context.Users
                    .AsNoTracking()
                    .FirstOrDefault(u => u.Id == id));

        public User GetUserById_Compiled(int id)
        {
            return GetUserById(_context, id);
        }

        // 批量更新（EF Core 7+）
        public async Task DeactivateOldUsers(int days)
        {
            var cutoffDate = DateTime.UtcNow.AddDays(-days);

            await _context.Users
                .Where(u => u.CreatedAt < cutoffDate && u.IsActive)
                .ExecuteUpdateAsync(s => s
                    .SetProperty(u => u.IsActive, false));
        }

        // 批量删除（EF Core 7+）
        public async Task DeleteInactiveUsers()
        {
            await _context.Users
                .Where(u => !u.IsActive)
                .ExecuteDeleteAsync();
        }

        // 批量插入
        public async Task BulkInsertUsers(List<User> users)
        {
            // 使用 AddRange
            await _context.Users.AddRangeAsync(users);
            await _context.SaveChangesAsync();
        }

        // 使用 Any 而非 Count
        public async Task<bool> HasActiveUsers()
        {
            // 推荐
            return await _context.Users.AnyAsync(u => u.IsActive);

            // 不推荐
            // return await _context.Users.CountAsync(u => u.IsActive) > 0;
        }

        // 查询性能监控
        public async Task<List<User>> GetUsersWithMonitoring()
        {
            var stopwatch = Stopwatch.StartNew();

            var users = await _context.Users
                .AsNoTracking()
                .Where(u => u.IsActive)
                .ToListAsync();

            stopwatch.Stop();
            _logger.LogInformation($"查询用户耗时: {stopwatch.ElapsedMilliseconds}ms，" +
                                   $"返回 {users.Count} 条记录");

            return users;
        }

        // 编译查询
        private static readonly Func<PerformanceDbContext, IAsyncEnumerable<User>> GetActiveUsers =
            EF.CompileAsyncQuery((PerformanceDbContext context) =>
                context.Users.Where(u => u.IsActive));

        public async Task<List<User>> GetActiveUsers_Compiled()
        {
            var users = new List<User>();
            await foreach (var user in GetActiveUsers(_context))
            {
                users.Add(user);
            }
            return users;
        }
    }

    public class UserDto
    {
        public int Id { get; set; }
        public string Name { get; set; }
        public int OrderCount { get; set; }
        public decimal TotalSpent { get; set; }
    }

    // 读写分离示例
    public class ReadWriteSeparationExample
    {
        private readonly PerformanceDbContext _readContext;
        private readonly PerformanceDbContext _writeContext;

        public ReadWriteSeparationExample(
            [FromKeyedServices("Read")] PerformanceDbContext readContext,
            [FromKeyedServices("Write")] PerformanceDbContext writeContext)
        {
            _readContext = readContext;
            _writeContext = writeContext;
        }

        public async Task<User> GetUserAsync(int id)
        {
            // 从读库查询
            return await _readContext.Users
                .AsNoTracking()
                .FirstOrDefaultAsync(u => u.Id == id);
        }

        public async Task UpdateUserAsync(User user)
        {
            // 写入主库
            _writeContext.Users.Update(user);
            await _writeContext.SaveChangesAsync();
        }
    }

    // 配置服务
    public static class PerformanceServiceCollectionExtensions
    {
        public static IServiceCollection AddPerformanceDbContext(
            this IServiceCollection services,
            string readConnectionString,
            string writeConnectionString)
        {
            // 读库
            services.AddDbContext<PerformanceDbContext>(
                options => options
                    .UseSqlServer(readConnectionString)
                    .UseQueryTrackingBehavior(QueryTrackingBehavior.NoTracking),
                contextLifetime: ServiceLifetime.Scoped,
                optionsLifetime: ServiceLifetime.Singleton);

            // 写库
            services.AddKeyedDbContext<PerformanceDbContext>("Write",
                options => options
                    .UseSqlServer(writeConnectionString)
                    .LogTo(Console.WriteLine, LogLevel.Information));

            return services;
        }
    }
}
